 for name,x in R[R.family=='llm_encoder'].iterrows():rows.append([D.EN_NAME.get(name,name),f'{x.mse:.4f}',f'{x.mse/R.loc["miflu","mse"]:.2f}×',f'{x.PTE:.3f}',f'{x.PIE:.3f}',f'{int(x.passes)}/16'])
 return table('Frozen encoders with shared linear readout','冻结编码器加共享线性读出',[C('Encoder','编码器'),'MSE',C('vs MIFlu','相对 MIFlu'),'PTE','PIE (%)',C('Passes','通过')],rows,[5.6,2.1,2.1,2.1,2.1,2.1],8.3,C('11 retained encoders × 4 horizons × 3 seeds = 132 cells. The historical plan included two additional embedding-only arms, giving 156 planned cells; those 24 omitted cells are outside the 28-model roster. The result tests only this frozen-feature pipeline.','11 个保留编码器 × 4 跨度 × 3 种子 = 132 单元。历史计划还包含两个仅嵌入模型，总计 156 单元；未纳入的 24 单元不属于 28 模型正式名单。此结果只评价该冻结特征流程。'))
